/**
* `nextly_schema_owners` — who owns each table, PostgreSQL.
*
* One row per table, answering two questions that look like one and are not:
* WHO DECLARED it (`owner_kind`/`owner_id`) and WHICH MIGRATION STREAM CARRIES
* it (`migrated_by`). A plugin-contributed collection is declared by the
* plugin and migrated by the app, so a single "owner" column would have to be
* wrong about one of them.
*
* ## Why a table rather than deriving it from config
*
* The config says what SHOULD exist. This says what DOES, and the difference
* is the whole point: a table whose plugin has been removed from config is
* exactly the case where dropping it would destroy data, and config can no
* longer tell you it was ever a plugin's. A row that outlives the declaration
* is what makes an uninstall a decision rather than an accident.
*
* A table with NO row is never dropped by any path. Absence means "nobody has
* claimed this", which is the safe answer, not an invitation.
*
* @module schemas/schema-owners/postgres
*/
const nextlySchemaOwners = pgTable(SCHEMA_OWNERS_TABLE, {
	tableName: text("table_name"),
	/**
	* Which KIND of thing this row claims: `table` (the default, and what
	* every pre-element row was) or `column` | `index` | `fk` | `check` —
	* an ELEMENT somebody added to a table another owner declared.
	*/
	elementKind: text("element_kind").notNull().default("table"),
	/** The element's name; `''` for a table-level row. */
	elementName: text("element_name").notNull().default(""),
	/** `core` | `collection` | `single` | `component` | `plugin` | `app`. */
	ownerKind: text("owner_kind").notNull(),
	/** `nextly` | entity slug | plugin name | `app`. */
	ownerId: text("owner_id").notNull(),
	/**
	* Which migration stream carries this table: `core`, `app`, or
	* `plugin:<name>`. Distinct from who declared it.
	*/
	migratedBy: text("migrated_by").notNull(),
	ownerVersion: text("owner_version"),
	schemaVersion: integer("schema_version"),
	/** `active` | `orphaned` | `uninstalled`. */
	state: text("state").notNull(),
	createdAt: timestamp("created_at", { withTimezone: true }).notNull(),
	updatedAt: timestamp("updated_at", { withTimezone: true }).notNull()
}, (t) => [primaryKey({ columns: [
	t.tableName,
	t.elementKind,
	t.elementName
] })]);
// src/schemas/widget-layout/postgres.ts
/**
* `nextly_widget_layout` — one reader's arrangement of the dashboard, PostgreSQL.
*
* A row exists only for a scope that has arranged the dashboard at all. Absent,
* the reader sees the registry's own order, which is exactly today's behaviour
* — so shipping this table changes nothing for anybody until they move a card.
*
* ## Why `id` is a digest
*
* `id` holds a sha256 of `scopeKind:scopeId` rather than that string spelled
* out. The readable form does not fit: this column is `varchar(191)` — the
* width MySQL will index for a utf8mb4 key — while a user id is itself
* `varchar(191)` on MySQL and unbounded `text` on PostgreSQL, so `user:` plus
* an id past 186 characters overruns the key. Those accounts could read the
* endpoint, because an absent row is a legal answer, and failed on every save.
*
* 🔴 Do NOT construct this key by hand. A readable `user:<id>` matches no
* stored row, so a cleanup query or a migration written from an out-of-date
* reading of this comment silently affects nothing. `layoutRowId` in
* `schemas/widget-layout/index.ts` is the one derivation, and every reader,
* writer and deleter goes through it — which is also what lets the user
* deletion path address a row without importing the layout service.
*
* `scope_kind` and `scope_id` remain as their own readable columns, so an
* operator can still see whose row this is.
*
*
* ## Why the scope kind is in the key on day one
*
* Only `user` rows are written today. The kind is part of the key anyway,
* because it is half of what identifies an owner: keyed on the reader alone, a
* second kind of owner added after rows exist means migrating every row to make
* room for it. The column costs 32 bytes now and removes that migration.
*
* ## Why `layout` is `text` and not `jsonb`
*
* The `site_settings` convention (`custom_sidebar_groups`, `plugin_placements`),
* not the `nextly_meta` native-JSON one. A layout is read and written WHOLE —
* nothing ever queries a JSON path inside it — so native JSON buys nothing, and
* `jsonb` re-normalizes key order, which this repository has already paid for
* once in a "has this changed" comparison. A personalization feature invites
* exactly that comparison (an audit diff, a "your layout vs the team default"
* view), so the cheap thing to do now is the thing that will not need undoing.
*
* ## Why `version` is a column and not a timestamp
*
* A whole-document PUT needs to detect that somebody else wrote in between, and
* two tabs belonging to one person can write in the same second. An integer
* bumped per write is exact where a timestamp is merely usually right.
*
* @module schemas/widget-layout/postgres
*/
const nextlyWidgetLayout = pgTable("nextly_widget_layout", {
	id: varchar("id", { length: 191 }).primaryKey(),
	scopeKind: varchar("scope_kind", { length: 32 }).notNull(),
	scopeId: text("scope_id").notNull(),
	layout: text("layout").notNull(),
	version: integer("version").notNull().default(1),
	updatedAt: timestamp("updated_at", { withTimezone: true }).notNull()
});
// src/schemas/dynamic-singles/postgres.ts
/**
* PostgreSQL Schema for Dynamic Singles
*
* Defines the `dynamic_singles` table schema for PostgreSQL databases
* using Drizzle ORM. This schema stores metadata for both UI-created and
* code-first Singles with unified model fields for source tracking,
* migration status, and versioning.
*
* Singles are single-document entities for storing site-wide configuration
* such as site settings, navigation menus, footers, and homepage configurations.
*
* Key differences from Dynamic Collections:
* - `label` instead of `labels` (singular only, no plural form needed)
* - No `timestamps` column (Singles always have updatedAt)
* - No `hooks` column (Singles use code-only hooks via defineSingle())
*
* @module schemas/dynamic-singles/postgres
* @since 1.0.0
*
* @example
* ```typescript
* import {
*   dynamicSinglesPg,
*   type DynamicSinglePg,
*   type DynamicSingleInsertPg,
* } from '@nextly/schemas/dynamic-singles/postgres';
*
* // Insert a new Single
* const newSingle = await db.insert(dynamicSinglesPg).values({
*   slug: 'site-settings',
*   label: 'Site Settings',
*   tableName: 'single_site_settings',
*   fields: [...],
*   source: 'code',
*   schemaHash: 'abc123...',
* });
* ```
*/
/**
* PostgreSQL schema for the `dynamic_singles` table.
*
* Stores metadata for all Singles (UI-created, code-first, built-in)
* with unified model fields for:
* - Source tracking (code, ui, built-in)
* - Migration status (synced, pending, generated, applied)
* - Schema versioning and change detection
*
* @example
* ```typescript
* // Query all code-first Singles
* const codeSingles = await db
*   .select()
*   .from(dynamicSinglesPg)
*   .where(eq(dynamicSinglesPg.source, 'code'));
*
* // Find Singles needing migration
* const pendingMigrations = await db
*   .select()
*   .from(dynamicSinglesPg)
*   .where(eq(dynamicSinglesPg.migrationStatus, 'pending'));
* ```
*/
const dynamicSinglesPg = pgTable("dynamic_singles", {
	/** Unique identifier (UUID v4, auto-generated) */
	id: uuid("id").primaryKey().defaultRandom(),
	/**
	* Unique slug identifier for the Single.
	* Used in URLs and API endpoints (e.g., "site-settings", "header").
	* Must be unique across all Singles AND Collections.
	*/
	slug: varchar("slug", { length: 255 }).unique().notNull(),
	/**
	* Display label for the Admin UI.
	* Unlike Collections, Singles only need a singular label.
	*
	* @example 'Site Settings', 'Header Navigation', 'Footer'
	*/
	label: varchar("label", { length: 255 }).notNull(),
	/**
	* Database table name for this Single.
	* Must be unique across all tables.
	* Convention: prefix with `single_` (e.g., 'single_site_settings').
	*/
	tableName: varchar("table_name", { length: 255 }).unique().notNull(),
	/** Optional description of the Single's purpose */
	description: text("description"),
	/**
	* Field configurations defining the Single's document structure.
	* Supports all 26 field types from the Collections system.
	*/
	fields: jsonb("fields").$type().notNull(),
	/**
	* Admin UI configuration options.
	* Controls sidebar grouping, icon, visibility, etc.
	*/
	admin: jsonb("admin").$type(),
	/**
	* Where the Single was defined.
	* - 'code': defineSingle() in a config file
	* - 'ui': Visual Single Builder
	* - 'built-in': System Singles from Nextly core
	*/
	source: varchar("source", { length: 255 }).$type().default("ui").notNull(),
	/**
	* If true, the Single cannot be modified via the Admin UI.
	* Code-first Singles are locked by default.
	*/
	locked: boolean("locked").default(false).notNull(),
	/**
	* Whether the Single carries a Draft/Published status column.
	* Default false; users opt in via the Schema Builder modal. See the
	* collections postgres schema for full semantics.
	*/
	status: boolean("status").default(false).notNull(),
	/** Single-level i18n master switch (mirrors `status`). */
	localized: boolean("localized").default(false).notNull(),
	/**
	* Resolved content-versioning config for this single, or null when
	* unversioned. Stores the normalized `ResolvedVersionsConfig` (produced by
	* resolveVersionsConfig) so every consumer reads one canonical shape and
	* later stages (drafts, autosave, retention) read more fields without a
	* re-migration. Mirrors the collections schema.
	*/
	versions: jsonb("versions").$type(),
	/**
	* Cache-revalidation config (`{ tags?, disable? }`), a JSON column like
	* `versions` so `disable`/extra-`tags` reach the write path. Nullable when
	* the single sets no `revalidate` config.
	*/
	revalidate: jsonb("revalidate").$type(),
	/**
	* Webhook recording opt-out (`{ record: false }`). Nullable, and null means
	* record — so a database predating this column keeps recording exactly as
	* before and only an explicit opt-out suppresses the outbox.
	*/
	webhooks: jsonb("webhooks").$type(),
	/**
	* Path to the config file (code-first Singles only).
	* Used for syncing and displaying source location.
	* @example "src/singles/site-settings.ts"
	*/
	configPath: varchar("config_path", { length: 500 }),
	/**
	* SHA-256 hash of the fields definition.
	* Used for change detection during sync operations.
	*/
	schemaHash: varchar("schema_hash", { length: 64 }).notNull(),
	/**
	* Schema version number, incremented on each change.
	* Starts at 1 for new Singles.
	*/
	schemaVersion: integer("schema_version").default(1).notNull(),
	/**
	* Current migration status.
	* - 'synced': Schema matches database
	* - 'pending': Changes detected, migration needed
	* - 'generated': Migration file created
	* - 'applied': Migration applied to database
	*/
	migrationStatus: varchar("migration_status", { length: 20 }).$type().default("pending").notNull(),
	/**
	* Reference to the last applied migration ID.
	* Null for Singles that haven't been migrated yet.
	*/
	lastMigrationId: uuid("last_migration_id"),
	/** User ID who created the Single (optional) */
	createdBy: uuid("created_by"),
	/** When the Single was created */
	createdAt: timestamp("created_at", { withTimezone: false }).defaultNow().notNull(),
	/** When the Single was last updated */
	updatedAt: timestamp("updated_at", { withTimezone: false }).defaultNow().notNull()
}, (table) => [
	index("dynamic_singles_source_idx").on(table.source),
	index("dynamic_singles_migration_status_idx").on(table.migrationStatus),
	index("dynamic_singles_created_by_idx").on(table.createdBy),
	index("dynamic_singles_created_at_idx").on(table.createdAt),
	index("dynamic_singles_updated_at_idx").on(table.updatedAt)
]);
// src/schemas/site-settings/postgres.ts
/**
* PostgreSQL Schema for General Settings
*
* Defines the `site_settings` singleton table for PostgreSQL.
* Only one row ever exists (id = 'default').
*
* @module schemas/site-settings/postgres
* @since 1.0.0
*/
const siteSettingsPg = pgTable("site_settings", {
	/** Always 'default' — enforces singleton pattern. */
	id: text("id").primaryKey(),
	/** Display name for the application. */
	applicationName: varchar("application_name", { length: 255 }),
	/** Primary URL where the site is hosted. */
	siteUrl: varchar("site_url", { length: 2048 }),
	/** Primary email for administrative notifications. */
	adminEmail: varchar("admin_email", { length: 255 }),
	/** IANA timezone identifier, e.g. 'America/New_York'. */
	timezone: varchar("timezone", { length: 100 }),
	/** Date display format string, e.g. 'MM/DD/YYYY'. */
	dateFormat: varchar("date_format", { length: 50 }),
	/** Time display format: '12h' or '24h'. */
	timeFormat: varchar("time_format", { length: 50 }),
	/** URL of the logo image shown in the admin sidebar and auth pages. */
	logoUrl: varchar("logo_url", { length: 2048 }),
	/** URL of the logo image shown when the admin panel is in dark mode. */
	logoUrlDark: varchar("logo_url_dark", { length: 2048 }),
	/** JSON array of custom sidebar groups, e.g. [{"slug":"analytics","name":"Analytics","icon":"BarChart"}] */
	customSidebarGroups: text("custom_sidebar_groups"),
	/** JSON object mapping plugin slugs to sidebar group overrides, e.g. {"form-builder":"collections"} */
	pluginPlacements: text("plugin_placements"),
	/**
	* Revocation generation for preview links. Every preview token records the
	* generation it was minted under, and verification refuses a token whose
	* generation is not the current one — so incrementing this invalidates every
	* link ever issued, including sessions already in flight, with nothing to
	* store, sweep or replicate per token.
	*
	* Monotonic by contract: it only ever moves forward. Lowering it would
	* re-validate tokens that were already revoked, which is why the settings
	* form cannot write it.
	*/
	previewTokenGeneration: integer("preview_token_generation").notNull().default(0),
	/** When the settings were last updated. */
	updatedAt: timestamp("updated_at", { withTimezone: false }).defaultNow().notNull()
});
// src/schemas/user-field-definitions/postgres.ts
/**
* PostgreSQL Schema for User Field Definitions
*
* Defines the `user_field_definitions` table schema for PostgreSQL databases
* using Drizzle ORM. This schema stores metadata for custom user fields
* that extend the base user model, managed via `defineConfig()` (code)
* or the Admin Settings UI.
*
* @module schemas/user-field-definitions/postgres
* @since 1.0.0
*
* @example
* ```typescript
* import {
*   userFieldDefinitionsPg,
*   type UserFieldDefinitionPg,
*   type UserFieldDefinitionInsertPg,
* } from '../schemas/user-field-definitions/postgres';
*
* // Insert a new field definition
* await db.insert(userFieldDefinitionsPg).values({
*   name: 'company',
*   label: 'Company',
*   type: 'text',
*   source: 'ui',
* });
* ```
*/
/**
* PostgreSQL schema for the `user_field_definitions` table.
*
* Stores metadata for custom user fields that extend the base user model.
* Fields can be sourced from `defineConfig()` (code) or created via the
* Admin Settings > User Fields tab (ui).
*
* @example
* ```typescript
* // Query all active field definitions
* const fields = await db
*   .select()
*   .from(userFieldDefinitionsPg)
*   .where(eq(userFieldDefinitionsPg.isActive, true))
*   .orderBy(asc(userFieldDefinitionsPg.sortOrder));
*
* // Query code-sourced fields only
* const codeFields = await db
*   .select()
*   .from(userFieldDefinitionsPg)
*   .where(eq(userFieldDefinitionsPg.source, 'code'));
* ```
*/
const userFieldDefinitionsPg = pgTable("user_field_definitions", {
	/** Unique identifier (UUID v4, auto-generated) */
	id: uuid("id").primaryKey().defaultRandom(),
	/**
	* Unique field name used as the column name in `user_ext` table.
	* Must be a valid identifier (alphanumeric + underscores).
	* @example 'phoneNumber'
	*/
	name: varchar("name", { length: 255 }).notNull(),
	/**
	* Human-readable label displayed in the admin UI.
	* @example 'Phone Number'
	*/
	label: varchar("label", { length: 255 }).notNull(),
	/**
	* Field type determining the input component and column type.
	* One of: 'text', 'textarea', 'number', 'email', 'select', 'radio', 'checkbox', 'date'.
	*/
	type: varchar("type", { length: 50 }).$type().notNull(),
	/**
	* Whether this field is required when creating/updating a user.
	*/
	required: boolean("required").default(false).notNull(),
	/**
	* Default value for this field when creating a new user.
	* Stored as a string regardless of type (parsed at runtime).
	*/
	defaultValue: varchar("default_value", { length: 255 }),
	/**
	* Available options for `select` and `radio` field types.
	* Each option has a `label` (display text) and `value` (stored value).
	* Should be `null` for non-select/radio types.
	*/
	options: jsonb("options").$type(),
	/**
	* Options a plugin's own field type declared for this field.
	*
	* A contributed type states what it needs to render — a rating's scale, a
	* picker's source — and core cannot know those keys, so they are stored
	* whole rather than as columns. Without them the admin rebuilds the field
	* config from this row and hands the plugin's editor a field stripped of
	* its own declaration.
	*/
	pluginOptions: jsonb("plugin_options").$type(),
	/**
	* Whether a `select` field stores multiple values. Fixed at creation:
	* it decides the backing column's type (json when multiple, varchar
	* otherwise), and the reconciler only ever adds columns.
	*/
	hasMany: boolean("has_many"),
	/** Minimum string length for text/textarea values. */
	minLength: integer("min_length"),
	/** Maximum string length for text/textarea values; also sizes new varchar columns. */
	maxLength: integer("max_length"),
	/** Minimum numeric value for number fields. */
	minValue: doublePrecision("min_value"),
	/** Maximum numeric value for number fields. */
	maxValue: doublePrecision("max_value"),
	/**
	* Placeholder text shown in the input field.
	* @example 'Enter your phone number'
	*/
	placeholder: varchar("placeholder", { length: 255 }),
	/**
	* Help text / description shown below the input field.
	* @example 'Your company phone number including country code'
	*/
	description: text("description"),
	/**
	* Sort order for display in the admin UI.
	* Lower numbers appear first.
	*/
	sortOrder: integer("sort_order").default(0).notNull(),
	/**
	* Origin of this field definition.
	* - `code`: Synced from `defineConfig()` — read-only in admin UI
	* - `ui`: Created via admin Settings — fully editable
	*/
	source: varchar("source", { length: 10 }).$type().default("ui").notNull(),
	/**
	* Whether this field is currently active.
	* Inactive fields are stored but not rendered in forms or included in queries.
	*/
	isActive: boolean("is_active").default(true).notNull(),
	/** When the field definition was created */
	createdAt: timestamp("created_at", { withTimezone: false }).defaultNow().notNull(),
	/** When the field definition was last updated */
	updatedAt: timestamp("updated_at", { withTimezone: false }).defaultNow().notNull()
}, (table) => [
	uniqueIndex("user_field_defs_name_unique_idx").on(table.name),
	index("user_field_defs_source_idx").on(table.source),
	index("user_field_defs_is_active_idx").on(table.isActive),
	index("user_field_defs_sort_order_idx").on(table.sortOrder),
	index("user_field_defs_created_at_idx").on(table.createdAt)
]);
// src/schemas/email-providers/postgres.ts
/**
* PostgreSQL Schema for Email Providers
*
* Defines the `email_providers` table schema for PostgreSQL databases
* using Drizzle ORM. This schema stores email provider configurations
* (SMTP, Resend, SendLayer) managed via the Admin Settings UI.
*
* @module schemas/email-providers/postgres
* @since 1.0.0
*
* @example
* ```typescript
* import {
*   emailProvidersPg,
*   type EmailProviderPg,
*   type EmailProviderInsertPg,
* } from '../schemas/email-providers/postgres';
*
* // Insert a new provider
* await db.insert(emailProvidersPg).values({
*   name: 'Production SMTP',
*   type: 'smtp',
*   fromEmail: 'noreply@example.com',
*   configuration: { host: 'smtp.example.com', port: 587 },
* });
* ```
*/
/**
* PostgreSQL schema for the `email_providers` table.
*
* Stores email provider configurations managed through the admin
* Settings UI. Supports SMTP, Resend, and SendLayer providers.
* Sensitive fields in `configuration` (passwords, API keys) are
* encrypted at rest by the service layer.
*
* @example
* ```typescript
* // Query the default provider
* const defaultProvider = await db
*   .select()
*   .from(emailProvidersPg)
*   .where(eq(emailProvidersPg.isDefault, true))
*   .limit(1);
*
* // Query all active providers
* const activeProviders = await db
*   .select()
*   .from(emailProvidersPg)
*   .where(eq(emailProvidersPg.isActive, true));
* ```
*/
const emailProvidersPg = pgTable("email_providers", {
	/** Unique identifier (UUID v4, auto-generated) */
	id: uuid("id").primaryKey().defaultRandom(),
	/**
	* Display name for this provider.
	* @example 'Production SMTP', 'Resend API'
	*/
	name: varchar("name", { length: 255 }).notNull(),
	/**
	* Provider type determining which adapter is used for sending.
	* One of: 'smtp', 'resend', 'sendlayer'.
	*/
	type: varchar("type", { length: 50 }).$type().notNull(),
	/**
	* Default sender email address.
	* @example 'noreply@example.com'
	*/
	fromEmail: varchar("from_email", { length: 255 }).notNull(),
	/**
	* Default sender display name (optional).
	* @example 'My App'
	*/
	fromName: varchar("from_name", { length: 255 }),
	/**
	* Provider-specific configuration stored as JSONB.
	* Sensitive fields (passwords, API keys) are encrypted at rest.
	*
	* Shape depends on `type`:
	* - `smtp`: `{ host, port, secure, username, password }`
	* - `resend`: `{ apiKey }`
	* - `sendlayer`: `{ apiKey }`
	*/
	configuration: jsonb("configuration").$type().notNull(),
	/**
	* Whether this is the default provider for sending emails.
	* Only one provider can be default at a time (enforced by
	* partial unique index and service layer).
	*/
	isDefault: boolean("is_default").default(false).notNull(),
	/**
	* Whether this provider is currently active.
	* Inactive providers are stored but not used for sending.
	*/
	isActive: boolean("is_active").default(true).notNull(),
	/** When the provider was created */
	createdAt: timestamp("created_at", { withTimezone: false }).defaultNow().notNull(),
	/** When the provider was last updated */
	updatedAt: timestamp("updated_at", { withTimezone: false }).defaultNow().notNull()
}, (table) => [
	index("email_providers_type_idx").on(table.type),
	uniqueIndex("email_providers_default_unique_idx").on(table.isDefault).where(sql`${table.isDefault} = true`),
	index("email_providers_is_active_idx").on(table.isActive),
	index("email_providers_created_at_idx").on(table.createdAt)
]);
// src/schemas/email-deliveries/postgres.ts
/**
* PostgreSQL schema for the email delivery log.
*
* One row per RECIPIENT per send: which provider carried the message, which
* template produced it, whether that recipient was accepted, and a hash of the
* address. Together they answer "did this send", "how many are failing" and
* "did this person receive it" — the last for someone who was copied as much
* as for the primary recipient.
*
* ## What this table deliberately does not contain
*
* **The recipient's address.** Only a keyed hash of it, under the install's
* own secret. That answers "did this send" and "how many failed" without
* answering "to whom", and matches what the send path already does — it logs
* counts, never addresses. Support confirms a delivery by hashing the address
* they were given, which is the question they are actually asked, and the key
* is what leaves that query working while a stolen copy of the table cannot be
* enumerated: an email address has too little entropy for a bare digest to
* resist a dictionary.
*
* This reduces what the table discloses. It does not put the table outside
* identity-erasure obligations — a keyed hash of a person's address is
* pseudonymised data, and a request to erase a person still reaches these
* rows.
*
* **Two things erase them, for different populations.** Deleting a user account
* overwrites the `recipient_hash` of that person's rows with a sentinel no
* address hashes to, in the deletion's own transaction, and once more just
* after it commits, for a send that was already in flight. A send that writes
* its row after that second pass still leaves a live digest, until the
* retention pass removes the row by age: the erasure narrows that window rather
* than closing it. Someone who was only ever a recipient, with no account to
* delete, is erased the same way through the delivery service's
* `eraseRecipient`. Either way the row stays, because "how many sends failed
* last week" belongs to the install rather than to the recipient
* (`domains/email/erase-recipient.ts`). Apart from those requests, a retention
* pass deletes rows by age, scoped by `retention_class` below, which reaches
* every row whoever it was written for (`domains/email/prune.ts`).
*
* **The rendered subject.** The template SLUG is recorded instead. A slug says
* which kind of message this was, is stable across copy edits, and cannot carry
* a name — while a rendered subject is the single field in a message most
* likely to interpolate one. A raw send with no template records no slug, and
* the row still answers the question it exists for.
*
* **The message body.** Never, in any form.
*
* ## The retry columns are reserved and inert
*
* `status`, `attempt_count` and `next_attempt_at` exist from the first
* migration so that adding a drain later is not a migration on a table already
* holding production history. **Nothing drains this table today.**
*
* That distinction is load-bearing rather than pedantic, because a schema is
* read by more than the code that writes it. `next_attempt_at` is therefore
* always NULL: a timestamp in that column asserts that something will happen at
* that time, and an operator reading a failed row with a retry fifteen minutes
* out would wait for an attempt no code will ever make. A NULL is honestly
* empty; a populated column is a promise. `attempt_count` records attempts that
* actually happened, which is a fact rather than a promise, and is 1 for every
* row a log-only writer produces.
*
* @module schemas/email-deliveries/postgres
*/
const emailDeliveriesPg = pgTable("email_deliveries", {
	id: uuid("id").primaryKey().default(sql`gen_random_uuid()`),
	/**
	* The provider that carried the message, when one is still stored.
	*
	* `set null` rather than `cascade`: the delivery happened whether or not
	* the provider still exists, and deleting a provider must not erase the
	* evidence of what it sent. `provider_type` below is what survives.
	*/
	providerId: uuid("provider_id").references(() => emailProvidersPg.id, { onDelete: "set null" }),
	/**
	* The registered type, denormalized so the row stays meaningful after the
	* provider is deleted or its plugin uninstalled.
	*/
	providerType: varchar("provider_type", { length: 50 }).notNull(),
	/** Which template produced this, when one did. Never the rendered text. */
	templateSlug: varchar("template_slug", { length: 255 }),
	/**
	* Keyed SHA-256 of the lowercased, trimmed recipient address, hex encoded.
	*
	* Fixed width, so `char`-like sizing is honest; `varchar(64)` keeps the
	* three dialects aligned without a dialect-specific type.
	*/
	recipientHash: varchar("recipient_hash", { length: 64 }).notNull(),
	/**
	* How this recipient received the message: `to`, `cc` or `bcc`.
	*
	* One row per recipient, because the table's whole purpose is to answer
	* "did this person receive it", and a copied recipient received it just as
	* much as the primary one.
	*
	* Rows for one message share a `message_id` but NOT necessarily a
	* `status`. SMTP answers `RCPT TO` per address, so a server can accept the
	* message for some recipients and refuse it for others; a refused address
	* is recorded `failed` beside the accepted ones. A provider that reports a
	* single outcome for the whole message gives every row the same status,
	* which is the ordinary case rather than the guaranteed one.
	*
	* No column default. The recorder always supplies this, so a default would
	* only describe rows nothing writes — and the DDL renderer emits a string
	* default unquoted, which SQL rejects outright for a value that is also a
	* keyword.
	*/
	recipientKind: varchar("recipient_kind", { length: 3 }).notNull(),
	/**
	* `sent` or `failed`, PER RECIPIENT. A drain would add `pending` and
	* `retrying`.
	*/
	status: varchar("status", { length: 20 }).notNull(),
	/** Attempts actually made. Always 1 until something retries. */
	attemptCount: integer("attempt_count").notNull().default(1),
	/** Reserved for a drain. Always NULL today — see the module comment. */
	nextAttemptAt: timestamp("next_attempt_at", { withTimezone: true }),
	/**
	* Why it failed, with anything address-shaped removed.
	*
	* An SMTP rejection quotes the recipient back at you — `550 5.1.1
	* <someone@example.com> User unknown` — so storing a provider's message
	* verbatim would reintroduce the address this table hashes to avoid
	* holding, in the column right beside the hash.
	*/
	error: text("error"),
	/**
	* The provider's own id for the message, when it returned one.
	*
	* Unbounded, because the adapter contract accepts any string and a bounded
	* column would make a longer one a write error — which `record()` swallows
	* by design, so a message that WAS dispatched would end up with no row at
	* all. The log must not be the thing that decides a send is unrecordable.
	*/
	messageId: text("message_id"),
	/**
	* Which retention window governs this row.
	*
	* READ, unlike `next_attempt_at` above it. `domains/email/prune.ts` sweeps
	* by this column and by age, offered from the send path — rows are created
	* by sends, so that is when the table grows.
	*
	* The sweep scopes its DELETE by class, which is what makes an unswept
	* class invisible: one the writer can stamp but the pass does not scope for
	* matches no branch, is never selected, and grows while the pass reports
	* success. `EMAIL_RETENTION_CLASSES` is asserted against what the writer
	* can stamp so that failure is a red test rather than a silent table.
	*
	* Present from the first migration, for the reason the retry columns are:
	* adding it later would have been a migration on a table already holding
	* production history.
	*/
	retentionClass: varchar("retention_class", { length: 50 }).notNull(),
	/**
	* The plugin-defined person a plugin's email went to, by kind and id, on
	* the rows of its `to` recipients. Names no staff user: an address can
	* belong to a person and a staff user at once, and a person's deletion
	* erases only the rows that name them. Once the person is reported
	* deleted, the id is replaced by the keyed digest of kind and id.
	*/
	principalKind: varchar("principal_kind", { length: 191 }),
	principalId: varchar("principal_id", { length: 191 }),
	keyDigest: varchar("key_digest", { length: 64 }),
	createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow()
}, (t) => [
	index("email_deliveries_created_idx").on(t.createdAt),
	index("email_deliveries_recipient_idx").on(t.recipientHash, t.createdAt),
	index("email_deliveries_status_created_idx").on(t.status, t.createdAt),
	index("email_deliveries_provider_idx").on(t.providerId, t.createdAt),
	index("email_deliveries_retention_idx").on(t.retentionClass, t.createdAt),
	index("email_deliveries_principal_idx").on(t.principalKind, t.principalId),
	index("email_deliveries_key_idx").on(t.keyDigest)
]);
// src/schemas/email-send-claims/postgres.ts
/**
* `email_send_claims` — PostgreSQL definition.
*
* One row per idempotency key a caller has sent with: the claim core takes
* before contacting a provider, so a send that carries a key reaches the
* provider once however often it is repeated.
*
* Holds keyed digests and no address. The key is digested with its caller's
* scope, the message as everything that reaches the provider, and the first
* send's result carries recipients by position only. Times are epoch
* milliseconds, compared as numbers on every dialect.
*
* @module schemas/email-send-claims/postgres
*/
const emailSendClaimsPg = pgTable(EMAIL_SEND_CLAIMS_TABLE, {
	id: varchar("id", { length: 36 }).primaryKey(),
	/**
	* Who sent: `site`, `core`, `plugin:<name>`, or `rest` for a REST caller,
	* whose person or API key reaches only the key digest. Never chosen by a
	* caller, and unbounded, as a plugin's name is; the key digest includes
	* the full scope.
	*/
	scope: text("scope").notNull(),
	/**
	* Keyed digest of the scope and key, as the delivery records carry it.
	* Null once a person the send went to is erased.
	*/
	keyDigest: varchar("key_digest", { length: 64 }),
	/** Keyed digest of the message, to refuse a key reused for another. */
	messageDigest: varchar("message_digest", { length: 64 }),
	/** `claimed`, `sent` or `failed`. */
	state: varchar("state", { length: 16 }).notNull(),
	/** The attempt holding the claim, so only it can settle it. */
	holder: varchar("holder", { length: 36 }).notNull(),
	/** The first successful send's result, as JSON, with no address. */
	result: text("result"),
	claimedAt: bigint("claimed_at", { mode: "number" }).notNull(),
	/** After this a claim with no outcome may be taken over. */
	leaseExpiresAt: bigint("lease_expires_at", { mode: "number" }).notNull(),
	/** When the outcome was recorded; the lifetime of a sent claim runs from it. */
	settledAt: bigint("settled_at", { mode: "number" })
}, (t) => [
	uniqueIndex("email_send_claims_key_idx").on(t.keyDigest),
	index("email_send_claims_state_idx").on(t.state, t.settledAt),
	index("email_send_claims_lease_idx").on(t.leaseExpiresAt)
]);
// src/schemas/email-queue/postgres.ts
/**
* `email_queue` — PostgreSQL definition.
*
* One row per email queued through `queue` or `queueWithTemplate`: what is
* sent, held until it is, and where its attempts stand. The job that makes
* the attempts carries only this row's id, so the jobs table holds nothing
* of the message.
*
* The message is sealed under the install's secret (`queued-send.ts`), never
* held in clear. Times are epoch milliseconds, compared as numbers on every
* dialect.
*
* @module schemas/email-queue/postgres
*/
const emailQueuePg = pgTable(EMAIL_QUEUE_TABLE, {
	id: varchar("id", { length: 36 }).primaryKey(),
	/**
	* Who queued it: `site`, `core`, or `plugin:<name>`, the scope its
	* idempotency key is claimed in. Never chosen by a caller, and unbounded,
	* as a plugin's name is.
	*/
	scope: text("scope").notNull(),
	/** `waiting`, `sending`, `sent`, `failed` or `cancelled`. */
	state: varchar("state", { length: 16 }).notNull(),
	/** The job that makes its attempts; none for one stored cancelled. */
	jobId: varchar("job_id", { length: 36 }),
	/** The message, sealed: addresses, content and every send option. */
	message: text("message"),
	/**
	* The person `to` is, by kind and id, as the delivery records name them,
	* so their deletion cancels the email. Their digest in place of the id
	* once they are deleted.
	*/
	principalKind: varchar("principal_kind", { length: 191 }),
	principalId: varchar("principal_id", { length: 191 }),
	/** The last failed attempt's failure, as JSON, with no address. */
	failure: text("failure"),
	createdAt: bigint("created_at", { mode: "number" }).notNull(),
	updatedAt: bigint("updated_at", { mode: "number" }).notNull(),
	/** When it was sent, failed for good, or was cancelled. */
	settledAt: bigint("settled_at", { mode: "number" })
}, (t) => [index("email_queue_state_idx").on(t.state, t.settledAt), index("email_queue_principal_idx").on(t.principalKind, t.principalId)]);
// src/schemas/email-queue-recipients/postgres.ts
/**
* `email_queue_recipients` — PostgreSQL definition.
*
* One row per address a queued email goes to (`to`, `cc` and `bcc`), as the
* keyed digest the delivery records carry, never the address: what erasing
* an address finds a queued email by. Removed with the email's message.
*
* @module schemas/email-queue-recipients/postgres
*/
const emailQueueRecipientsPg = pgTable(EMAIL_QUEUE_RECIPIENTS_TABLE, {
	/** The queued email, `email_queue.id`. */
	queuedId: varchar("queued_id", { length: 36 }).notNull(),
	/** Keyed digest of the address, as `recipientDigest` makes it. */
	recipientHash: varchar("recipient_hash", { length: 64 }).notNull(),
	/**
	* `to`, `cc` or `bcc`, as the delivery records spell it. The person a
	* queued email names is its `to`; a copy is someone else.
	*/
	recipientKind: varchar("recipient_kind", { length: 8 }).notNull()
}, (t) => [primaryKey({ columns: [t.queuedId, t.recipientHash] }), index("email_queue_recipients_hash_idx").on(t.recipientHash)]);
// src/schemas/email-templates/postgres.ts
/**
* PostgreSQL Schema for Email Templates
*
* Defines the `email_templates` table schema for PostgreSQL databases
* using Drizzle ORM. This schema stores email templates with variable
* interpolation support, managed via the Admin Settings UI.
*
* @module schemas/email-templates/postgres
* @since 1.0.0
*
* @example
* ```typescript
* import {
*   emailTemplatesPg,
*   type EmailTemplatePg,
*   type EmailTemplateInsertPg,
* } from '../schemas/email-templates/postgres';
*
* // Insert a new template
* await db.insert(emailTemplatesPg).values({
*   name: 'Welcome Email',
*   slug: 'welcome',
*   subject: 'Welcome to {{appName}}, {{userName}}!',
*   htmlContent: '<h1>Welcome, {{userName}}!</h1>',
* });
* ```
*/
/**
* PostgreSQL schema for the `email_templates` table.
*
* Stores email templates with `{{variable}}` interpolation support.
* Templates can be managed via the admin Settings UI. Built-in
* templates (welcome, password-reset, email-verification) and
* layout templates (_email-header, _email-footer) are auto-created
* by the service layer.
*
* @example
* ```typescript
* // Query template by slug
* const template = await db
*   .select()
*   .from(emailTemplatesPg)
*   .where(eq(emailTemplatesPg.slug, 'password-reset'))
*   .limit(1);
*
* // Query all active templates
* const activeTemplates = await db
*   .select()
*   .from(emailTemplatesPg)
*   .where(eq(emailTemplatesPg.isActive, true));
* ```
*/
const emailTemplatesPg = pgTable("email_templates", {
	/** Unique identifier (UUID v4, auto-generated) */
	id: uuid("id").primaryKey().defaultRandom(),
	/**
	* Display name for this template.
	* @example 'Welcome Email', 'Password Reset'
	*/
	name: varchar("name", { length: 255 }).notNull(),
	/**
	* Unique identifier slug for programmatic access.
	* @example 'welcome', 'password-reset', '_email-header'
	*/
	slug: varchar("slug", { length: 255 }).unique().notNull(),
	/**
	* Email subject line. Supports `{{variable}}` interpolation.
	* @example 'Reset your {{appName}} password'
	*/
	subject: text("subject").notNull(),
	/**
	* HTML body content. Supports `{{variable}}` interpolation.
	* When `useLayout` is true, this content is wrapped with the
	* shared header/footer layout at send time.
	*/
	htmlContent: text("html_content").notNull(),
	/**
	* Optional plain text fallback content.
	* Supports `{{variable}}` interpolation.
	*/
	plainTextContent: text("plain_text_content"),
	/**
	* Inbox preview line shown after the subject in most clients.
	* Supports `{{variable}}` interpolation. Null renders no preheader.
	*/
	preheader: text("preheader"),
	/**
	* Row kind. `layout` rows are wrappers whose `htmlContent` holds a
	* `{{content}}` placeholder; `template` rows are message bodies;
	* `partial` rows are reusable fragments. Nullable so it adds cleanly
	* to existing tables; boot backfills nulls to `template` and a null
	* kind is treated as `template` on read.
	*/
	kind: varchar("kind", { length: 20 }).default("template"),
	/**
	* Layout that wraps this template at send time (`kind = 'layout'` row).
	* Null uses the default layout. Soft reference to another row's id
	* (no DB FK — integrity is enforced in the service so the column can
	* be added to existing tables without a table rebuild).
	*/
	layoutId: uuid("layout_id"),
	/**
	* Available template variables with descriptions.
	* Displayed in the admin UI template editor for reference.
	*/
	variables: jsonb("variables").$type(),
	/**
	* Whether to wrap `htmlContent` with the shared email
	* header/footer layout at send time.
	*/
	useLayout: boolean("use_layout").default(true).notNull(),
	/**
	* Whether this template is currently active.
	* Inactive templates are stored but cannot be used for sending.
	*/
	isActive: boolean("is_active").default(true).notNull(),
	/**
	* Optional provider ID to override the default email provider
	* for this specific template. When null, the system default is used.
	* Soft reference (no DB FK); the send path falls back to the default
	* provider when this points at a removed provider.
	*/
	providerId: uuid("provider_id"),
	/**
	* Per-template From override (e.g. `Support <help@example.com>`).
	* Null falls back to the provider / config From.
	*/
	fromOverride: text("from_override"),
	/** Per-template Reply-To address. Null sets no Reply-To header. */
	replyTo: text("reply_to"),
	/**
	* Fixed addresses copied on every send of the template, after the send's
	* own copies. Never variables, and never on a template carrying a secret.
	* Nullable, so it reaches an existing table as a plain ADD COLUMN.
	*/
	cc: jsonb("cc").$type(),
	/** Fixed addresses blind-copied on every send, on the same rules as `cc`. */
	bcc: jsonb("bcc").$type(),
	/**
	* Default attachments for this template. Merged with per-send
	* attachments at send time (dedupe by mediaId, per-send wins).
	* When null, no default attachments are applied.
	*/
	attachments: jsonb("attachments").$type(),
	/** Who owns the template: `core`, `plugin` or `site`. */
	ownerKind: varchar("owner_kind", { length: 20 }),
	/** The owning plugin's name, for `ownerKind = 'plugin'`; unbounded, as a plugin's name is. */
	ownerName: text("owner_name"),
	/**
	* Whether the site has overridden an owned template. While true the row
	* holds the site's version and owner updates wait for review; null reads
	* as false.
	*/
	overridden: boolean("overridden"),
	/** Digest of the owner's version an override started from. */
	baseDigest: varchar("base_digest", { length: 64 }),
	/**
	* The owner's version an override started from, kept so a later owner
	* update can be reviewed change by change against it.
	*/
	baseVersion: jsonb("base_version").$type(),
	/**
	* Whether the template's owner marks it as carrying a secret (a reset or
	* verification link). Written from the owner's declaration, never by an
	* edit; kept so a plugin that is not running keeps its mark. Null reads as
	* false.
	*/
	carriesSecret: boolean("carries_secret"),
	/** When the template is sent, written by its owner (or the site). */
	description: text("description"),
	/** When the template was created */
	createdAt: timestamp("created_at", { withTimezone: false }).defaultNow().notNull(),
	/** When the template was last updated */
	updatedAt: timestamp("updated_at", { withTimezone: false }).defaultNow().notNull()
}, (table) => [
	index("email_templates_is_active_idx").on(table.isActive),
	index("email_templates_provider_id_idx").on(table.providerId),
	index("email_templates_kind_idx").on(table.kind),
	index("email_templates_layout_id_idx").on(table.layoutId),
	index("email_templates_created_at_idx").on(table.createdAt)
]);
